def label(case, spec=None):
    if case in LABELS:
        return LABELS[case]
    if '_without_' in case:
        family, omitted = case.split('_without_', 1)
        target = {'alice': 'ALICE', 'atlas': 'ATLAS', 'cms': 'CMS',
                  'first_rg': r'first $r_g$ bins', 'first_dR12': r'first $dR_{12}$ bin',
                  'first_rg_and_dR12': r'first $r_g$/$dR_{12}$ bins'}.get(omitted)
        if target:
            return ('Inclusive' if family == 'inclusive' else 'Joint') + ': omit ' + target
    text = case.replace('without_', 'without ').replace('minus_', 'without ')
    text = text.replace('first_rg_and_dR12', 'first radius and splitting bins')
    text = text.replace('first_rg', 'first radius bins').replace('first_dR12', 'first splitting bin')
    text = text.replace('hpt10', 'hadron pT > 10 GeV')
    for token, name in (('alice', 'ALICE'), ('atlas', 'ATLAS'), ('cms', 'CMS')):
        text = text.replace(token, name)
    text = text.replace('inclusive', 'Inclusive').replace('all', 'Joint').replace('_', ' ')
    if text == case:
        supplied = (spec or {}).get('display_label') or (spec or {}).get('label')
        if supplied:
            return supplied
    return text


def style(case):
    role = ROLE.get(case, 'default')
    if '_without_' in case:
        role = {'alice': 'blue', 'atlas': 'vermillion', 'cms': 'purple',
                'first_rg': 'blue', 'first_dR12': 'vermillion',
                'first_rg_and_dR12': 'purple'}[case.split('_without_', 1)[1]]
    if role == 'grey':
        return dict(color='#62666A', linestyle='--')
    selected = {key: value for key, value in hp.comparison_style(role).items()
                if key in ('color', 'linestyle')}
    if case == 'theta_g':
        selected['linestyle'] = '-.'
    return selected


def features(value):
    out = [(str(name), float(low), float(high)) for name, low, high in value]
    if len(set(out)) != len(out) or any(not np.isfinite([a, b]).all() or a >= b for _, a, b in out):
        raise ValueError('Invalid or duplicate feature identities')
    return out


def validate_grid(grid, mass_key='mass'):
    q, k = grid['q'], grid['kappa']
    mass = grid[mass_key]
    if (q.ndim != 1 or k.ndim != 1 or len(q) < 3 or len(k) < 3
            or not np.isfinite(q).all() or not np.isfinite(k).all()
            or np.any(np.diff(q) <= 0) or np.any(np.diff(k) <= 0)
            or not np.allclose(q[[0, -1]], [0, 20], atol=1e-10, rtol=0)
            or not np.allclose(k[[0, -1]], [.3, .6], atol=1e-10, rtol=0)
            or mass.shape != (len(q), len(k)) or not np.isfinite(mass).all()
            or np.any(mass < 0) or not np.isclose(mass.sum(), 1, atol=1e-9, rtol=0)):
        raise ValueError('Invalid full-support physical posterior: ' + mass_key)


def resolution_axis(ax):
    ax.set_xscale('symlog', linthresh=1)
    ax.set_xlim(0, 20)
    ax.xaxis.set_major_locator(FixedLocator([0, 1, 2, 5, 10, 20]))
    ax.xaxis.set_major_formatter(ScalarFormatter())
    ax.set_xlabel(hp.LRES_LABEL)
    hp.frame_axes(ax, minor=False)


def handle(text, role):
    return Line2D([], [], label=text, lw=2.5, **role)


def posterior_overlay(book, results, cases, stem, title, geom, *, roles=None, labels=None):
    chosen = [case for case in cases if case in results]
    if not chosen:
        return
    fig, (joint, marginal) = plt.subplots(2, 1, figsize=(7.15, 7.5), sharex=True,
                                         gridspec_kw={'height_ratios': [1.35, 1]})
    legend = []
    checks = {}
    for case in chosen:
        row = results[case]
        role = (roles or {}).get(case, style(case))
        q, k, mass = (row.grid[key] for key in ('q', 'kappa', 'mass'))
        density, levels = geom.density_and_levels(mass, q, k)
        joint.contour(q, k, density.T, levels=levels, colors=[role['color']],
                      linewidths=[1.1, 2.4], linestyles=[role['linestyle']])
        marginal.plot(q, mass.sum(1) / geom.weights(q), lw=2.2, **role)
        legend.append(handle((labels or {}).get(case, label(case, row.spec)), role))
        checks[case] = dict(full_support_mass=float(mass.sum()), levels_95_68=list(map(float, levels)))
    joint.set(ylabel=hp.KAPPA_LABEL, ylim=(.3, .6))
    marginal.set(ylabel='Posterior density', ylim=(0, None))
    for ax in (joint, marginal):
        resolution_axis(ax)
        ax.tick_params(labelsize=12)
    joint.set_xlabel('')
    fig.legend(handles=legend, loc='upper center', bbox_to_anchor=(.53, .935),
               ncol=2 if len(chosen) > 2 else len(chosen), fontsize=12.5)
    fig.suptitle(title, y=.985, fontsize=15)
    fig.subplots_adjust(left=.15, right=.97, top=.77 if len(chosen) > 4 else .81,
                        bottom=.11, hspace=.08)
    book.checks[stem] = checks
    book.save(fig, stem, title, chosen, 'Physical density; 68% thick / 95% thin. Full 0-20 support; no display renormalization.')


