    if not rows:
        return
    if len(rows) > 10:
        for start in range(0, len(rows), 10):
            intervals(book, rows[start:start+10], stem + f'_{start//10+1:02d}', title)
        return
    fig, aa = plt.subplots(1, 2, figsize=(9., max(3.6, .42 * len(rows) + 1.5)), sharey=True)
    for i, (text, q, k, role) in enumerate(rows):
        y = len(rows) - 1 - i
        for ax, value in zip(aa, (q, k)):
            low, mid, high = value
            if not np.isfinite(value).all() or not low <= mid <= high:
                raise ValueError('Invalid saved posterior interval')
            ax.errorbar(mid, y, xerr=np.array([[mid-low], [high-mid]]), fmt='o',
                        color=role['color'], capsize=3, ms=4.8, lw=1.8)
    aa[0].set(yticks=np.arange(len(rows)), yticklabels=[row[0] for row in rows[::-1]],
              xlabel=hp.LRES_LABEL, xlim=(0, 20), ylim=(-.7, len(rows)-.3))
    aa[1].set(xlabel=hp.KAPPA_LABEL, xlim=(.3, .6))
    aa[1].tick_params(labelleft=False)
    for ax in aa:
        ax.tick_params(labelsize=11)
        hp.frame_axes(ax, minor=False)
    fig.suptitle(title, fontsize=15)
    fig.subplots_adjust(left=.46, right=.98, top=.88, bottom=.19, wspace=.18)
    book.save(fig, stem, title, [], 'Saved 16th/50th/84th percentiles; overlapping data selections are not independent measurements.')


