def observable_title(name):
    collaboration = next((word.upper() for word in ('alice', 'atlas', 'cms') if '_' + word in name), '')
    centrality = name.split('__')[-1] + '%'
    if '__hadron__' in name:
        return collaboration + ' charged hadrons, ' + centrality, r'$p_T$ [GeV]', 'log', hp.RAA_LABEL
    if '__inclusive_jet__pt_' in name:
        radius = re.search(r'__R([0-9.]+)', name)
        extra = ', R=' + radius.group(1) if radius else ''
        return collaboration + ' jets' + extra, r'$p_T$ [GeV]', 'log', hp.RAA_LABEL
    if '__tg_' in name:
        return collaboration + r' $\theta_g$', r'$\theta_g$', 'linear', 'Distribution ratio'
    if '__dr12_' in name:
        return collaboration + r' $dR_{12}$', r'$dR_{12}$', 'linear', hp.RAA_LABEL
    if '__rg_' in name:
        token = re.search(r'_pt([012])', name)
        pt = ('158-200', '200-315', '315-501')[int(token.group(1))] if token else ''
        return collaboration + r' $r_g$, ' + pt + ' GeV', r'$r_g$', 'symlog', hp.RAA_LABEL
    raise ValueError('Unrecognized observable, refusing a raw case-ID label: ' + name)


def draw_observable(ax, name, row, y, error):
    ff = features(row.predictive['features170'])
    ix = [i for i, feature in enumerate(ff) if feature[0] == name]
    selected = set(features(row.spec['features']))
    qq = row.predictive['quantiles']
    role = style(row.case)
    title, xlabel, scale, ylabel = observable_title(name)
    for i in ix:
        _, low, high = ff[i]
        own = ff[i] in selected
        ax.fill_between([low, high], [qq[1, i]] * 2, [qq[3, i]] * 2,
                        color=role['color'], alpha=.22 if own else .11)
        ax.plot([low, high], [qq[2, i]] * 2, color=role['color'], lw=2,
                linestyle='-' if own else '--')
    center = np.array([(ff[i][1] + ff[i][2]) / 2 for i in ix])
    fitted = np.array([ff[i] in selected for i in ix])
    for mask, color, fill in ((fitted, '#202326', '#202326'), (~fitted, '#777777', 'white')):
        if mask.any():
            ax.errorbar(center[mask], y[ix][mask], yerr=error[ix][mask], fmt='o',
                        color=color, markerfacecolor=fill, ms=3.5, capsize=2, lw=1)
    ax.set(xlabel=xlabel, ylabel=ylabel, title=title)
    if scale == 'symlog':
        ax.set_xscale('symlog', linthresh=.003)
        ax.set_xticks([0, .003, .01, .1, .4])
        ax.xaxis.set_major_formatter(ScalarFormatter())
    else:
        ax.set_xscale(scale)
        if scale == 'log':
            ax.xaxis.set_major_locator(LogLocator(base=10, subs=(1, 2, 5)))
            ax.xaxis.set_major_formatter(FuncFormatter(lambda value, _: f'{value:g}'))
            ax.xaxis.set_minor_formatter(NullFormatter())
    ax.set_xlim(min(ff[i][1] for i in ix), max(ff[i][2] for i in ix))
    ax.set_ylim(bottom=0)
    ax.tick_params(labelsize=10)
    ax.xaxis.label.set_fontsize(12)
    ax.yaxis.label.set_fontsize(12)
    ax.title.set_fontsize(12)
    hp.frame_axes(ax, minor=False)
    return dict(observable=name, indices=ix, fitted_indices=[i for i in ix if ff[i] in selected],
                auxiliary_indices=[i for i in ix if ff[i] not in selected])


def galleries(book, results, y, error):
    for case, row in results.items():
        names = list(dict.fromkeys(feature[0] for feature in features(row.predictive['features170'])))
        coverage = []
        for start in range(0, len(names), 6):
            fig, axes = plt.subplots(3, 2, figsize=(7.15, 8.7))
            for ax, name in zip(axes.ravel(), names[start:start+6]):
                coverage.append(draw_observable(ax, name, row, y, error))
            for ax in axes.ravel()[len(names[start:start+6]):]:
                ax.set_axis_off()
            fig.suptitle('Observable predictions: ' + label(case, row.spec), fontsize=15, y=.995)
            fig.legend(handles=[Patch(facecolor=style(case)['color'], alpha=.22, label='68% prediction interval'),
                                Line2D([], [], color='#555555', ls='--', label='Unfitted: auxiliary prediction'),
                                Line2D([], [], color='#555555', marker='o', mfc='white', lw=0, label='Unfitted data')],
                       loc='upper center', bbox_to_anchor=(.53, .966), ncol=2, fontsize=10.5)
            fig.subplots_adjust(left=.12, right=.97, top=.85, bottom=.105, hspace=.64, wspace=.36)
            book.save(fig, f'observables_{case}_{start//6+1:02d}', 'Observable predictions: ' + label(case), [case],
                      'Bands: parameter + latent emulator uncertainty. Bars: full experimental marginal errors. '
                      + ('Saved band-precision check passed.' if row.summary['predictive_precision']['predictive_band_converged']
                         else 'WARNING: saved band-precision check failed; review before interpretation.'))
        covered = [i for item in coverage for i in item['indices']]
        if sorted(covered) != list(range(170)):
            raise ValueError('Incomplete or repeated observable gallery: ' + case)
        book.checks['gallery_' + case] = coverage


def prior_figures(book, results, v2):
    for case, row in results.items():
        if row.prior is None:
            continue
        data = row.prior
        q, k = data['q'], data['kappa']
        physical = data['physical_mass']
        square = data['square_mass']
        u = data['u']
        if (physical.shape != (len(q), len(k)) or square.shape != (len(u), len(k))
                or u[0] != 0 or u[-1] != 1 or not np.isclose(square.sum(), 1, atol=1e-9)):
            raise ValueError('Prior comparison lacks full unit-square support: ' + case)
        validate_grid(dict(q=q, kappa=k, mass=physical))
        fig, aa = plt.subplots(1, 2, figsize=(7.15, 4.5), sharey=True)
        geo = v2.base.geometry
        density, levels = geo.density_and_levels(physical, q, k)
        full_q, full_density, full_levels, enclosed = v2.physical_square_contours(square, u, k)
        same = data['square_same_support_mass']
        validate_grid(dict(q=q, kappa=k, mass=same))
        same_u = (2/np.pi)*np.arctan(np.cbrt(q))
        jacobian = np.empty_like(q)
        jacobian[0] = geo.weights(same_u)[0] / np.tan(.25*np.pi*same_u[1])**3
        jacobian[1:] = (2/(3*np.pi))*q[1:]**(-2/3)/(1+q[1:]**(2/3))
        same_density = same / (geo.weights(same_u)[:, None]*geo.weights(k)[None, :]) * jacobian[:, None]
        same_levels = density_levels(same_density, same)
        roles = [hp.comparison_style('default'), hp.comparison_style('blue')]
        for ax, xx, dd, ll, title in (
                (aa[0], full_q[:-1], full_density[:-1], full_levels, 'Full unit-square support'),
                (aa[1], q, same_density, same_levels, 'Same physical support, 0-20')):
            ax.contour(q, k, density.T, levels=levels, colors=[roles[0]['color']], linewidths=[1.1, 2.4])
            ax.contour(xx, k, dd.T, levels=ll, colors=[roles[1]['color']],
                       linestyles=[roles[1]['linestyle']], linewidths=[1.1, 2.4])
            resolution_axis(ax)
            ax.set(title=title, ylim=(.3, .6))
            ax.title.set_fontsize(12)
        aa[0].set_ylabel(hp.KAPPA_LABEL)
        tail_mass = row.prior_summary['cases'][case]['square']['posterior_mass_above_20']
        aa[0].text(.04, .96, f'Square-prior mass above 20: {100*tail_mass:.2g}%',
                   transform=aa[0].transAxes, fontsize=9.5, va='top')
        fig.suptitle('Joint prior sensitivity: ' + label(case), fontsize=15)
        fig.legend(handles=[handle('Uniform physical resolution', roles[0]), handle('Uniform unit coordinate', roles[1])],
                   loc='upper center', bbox_to_anchor=(.53, .93), ncol=2, fontsize=11)
        fig.subplots_adjust(left=.13, right=.98, top=.74, bottom=.20, wspace=.15)
        book.checks['prior_' + case] = dict(square_levels_use_full_support=True,
            enclosed_full_square_95_68=enclosed, saved_summary=row.prior_summary,
            same_support_boundary_density=float(same_density[-1].max()))
        book.save(fig, 'prior_joint_' + case, 'Joint prior sensitivity: ' + label(case), [case],
                  'Same selected model and likelihood. Full-square contours are not renormalized to the displayed range; boundary extrapolation remains.')


def density_levels(density, mass):
    order = np.argsort(density.ravel())[::-1]
    cumulative = np.cumsum(mass.ravel()[order])
    return [float(density.ravel()[order[min(np.searchsorted(cumulative, p), len(order)-1)]]) for p in (.95, .68)]

